def remplir_t(t):
    f1 = open("chaine.txt", "r")
    ch = f1.readline()
    while ch != "":
        for i in range(len(ch)):
            if "A" <= ch[i].upper() <= "Z":
                t[ord(ch[i].upper()) - 65] += 1
        ch = f1.readline()
    f1.close()

def remplir_f2(t):
    f2 = open("frequence.txt", "w")
    for i in range(26):
        ch = "la frequence de " + chr(i + 65) + "=" + str(t[i]) + "\n"
        f2.write(ch)
    f2.close()
